const sessionUser=JSON.parse(sessionStorage.getItem('shotcraftUser')||'{}');
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
async function signOut(){try{await fetch('/api/auth/logout',{method:'POST'})}finally{sessionStorage.removeItem('shotcraftUser');location.replace('/auth?mode=login')}}
document.body.classList.add('photographer-app');
const app=document.getElementById('app');
let timelineRequest=0;
const timelineMarkup=items=>`<section class="shared-timeline"><div class="eyebrow">Shoot journey</div><div class="timeline-track">${(items||[]).map(item=>`<div class="timeline-item ${item.completed?'complete':''}"><span class="timeline-dot">${item.completed?'✓':''}</span><div><b>${esc(item.label)}</b><small>${item.timestamp?esc(item.timestamp):'Upcoming'}</small></div></div>`).join('')}</div></section>`;
async function refreshTimeline(){const id=app.dataset.timelineId;if(!id)return;const request=++timelineRequest;try{const response=await fetch(`/api/inquiries/${id}/timeline`,{cache:'no-store'}),data=await response.json();if(request!==timelineRequest)return;const existing=document.querySelector('.shared-timeline');if(existing)existing.outerHTML=timelineMarkup(data.timeline);else {const legacy=document.querySelector('.progress');if(legacy)legacy.outerHTML=timelineMarkup(data.timeline);else app.insertAdjacentHTML('beforeend',timelineMarkup(data.timeline))}}catch(_){} }
const briefCache=new Map();
let inquiries=[],cityImages={};
let current={view:'overview',id:null};
document.getElementById('photographerName').textContent=sessionUser.name||'Photographer';
document.getElementById('photographerEmail').textContent=sessionUser.email||'';
document.querySelector('.sidebar')?.insertAdjacentHTML('beforeend','<button class="link sign-out" type="button">Sign out</button>');
document.querySelector('.sign-out')?.addEventListener('click',signOut);
document.querySelector('.brand').innerHTML='<span class="brand-mark logo-image"><img src="/static/brand/shotcraft-mark.png" alt=""></span><span class="brand-copy"><b>ShotCraft</b><small>Creative workspace</small></span>';
document.querySelector('.identity').insertAdjacentHTML('afterbegin',sessionUser.profile_image?`<span class="profile-orb profile-orb-image"><img src="${esc(sessionUser.profile_image)}" alt=""></span>`:'<span class="profile-orb" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm7 8a7 7 0 0 0-14 0"/></svg></span>');
document.querySelector('.identity').insertAdjacentHTML('beforeend','<span class="account-menu">•••</span>');
document.querySelector('.nav').innerHTML='<div class="nav-label">Workspace</div><button data-view="overview"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M4 11 12 4l8 7v9h-5v-6H9v6H4Z"/></svg></span><span>Overview</span></button><button data-view="inquiries"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M4 6.5h16v11H4zM8 10h8M8 14h5"/></svg></span><span>Inquiry inbox</span><span class="nav-count" id="inboxCount"></span></button><button data-view="projects"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M4 7h6l2-2h8v14H4Z"/></svg></span><span>Active projects</span></button><button data-view="calendar"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M5 5h14v15H5zM8 3v4M16 3v4M5 9h14"/></svg></span><span>Shoot calendar</span></button>';
const parse=value=>{try{return typeof value==='string'?JSON.parse(value):value}catch{return null}};
const formatDate=value=>{if(!value)return'Date flexible';const date=new Date(value);const hasTime=value.includes('T')||/^\d{4}-\d{2}-\d{2}\s/.test(value);return Number.isNaN(date.valueOf())?value:date.toLocaleString(undefined,{dateStyle:'medium',...(hasTime?{timeStyle:'short'}:{})})};
function payload(record){return parse(record.payload)||{}}
function statusInfo(record){if(record.status==='SCHEDULED')return['SHOOT SCHEDULED','scheduled'];if(record.status==='CLIENT_CONFIRMED')return['CLIENT CONFIRMED','ready'];if(record.status==='CLIENT_CHANGE_REQUESTED')return['CHANGE REQUESTED','needs'];if(record.production_approved)return['PLAN SHARED','ready'];if(record.production_pack)return['PLAN READY','ready'];if(record.moodboard){const mood=parse(record.moodboard);return[mood?.generated?.tiles?.length?'MOODBOARD RENDERED':'MOODBOARD PLAN READY','ready']}if(record.status==='READY_FOR_REVIEW')return['READY TO PLAN','ready'];if(record.status==='NEEDS_INFORMATION')return['AWAITING CLIENT','needs'];return[record.status.replaceAll('_',' '),'']}
function setNav(view){document.querySelectorAll('.nav button').forEach(button=>button.classList.toggle('active',button.dataset.view===view||(['project','brief','production','schedule'].includes(view)&&button.dataset.view==='projects')))}
function go(view,id=null,push=true){current={view,id:id?Number(id):null};if(push){const params=new URLSearchParams();if(view!=='overview')params.set('view',view);if(id)params.set('id',id);history.pushState(current,'','/photographer'+(params.size?'?'+params:''))}renderCurrent()}
function recordCard(record){const p=payload(record),status=statusInfo(record);return`<article class="card project"><div class="row"><div><b>${esc(p.client_name||'Unnamed client')}</b><p class="project-summary">${esc((p.message||'').slice(0,180))}${(p.message||'').length>180?'…':''}</p></div><span class="status ${status[1]}">${status[0]}</span></div><div class="meta"><div>Shoot date<b>${esc(formatDate(p.shoot_date))}</b></div><div>Budget<b>${p.budget?'$'+esc(p.budget):'Not specified'}</b></div></div><button class="primary" data-project="${record.id}">Open project →</button></article>`}
function projectTitle(record){const p=payload(record),analysis=parse(record.analysis)||{},originalRequest=String(p.message||'').split(/\n\s*Client follow-up answers:|\n{2,}/i)[0].trim();return analysis.concept_name||p.shoot_type||originalRequest.split(/[.!?]/)[0]?.slice(0,58)||`${p.client_name||'Client'} shoot`}
function projectLocation(record){const p=payload(record),text=[p.message,record.meeting_location].filter(Boolean).join(' '),city=text.match(/Seattle|Delhi|New Delhi/i)?.[0]?.toLowerCase().replace('new delhi','delhi');return{city,label:record.meeting_location||(city==='delhi'?'Delhi, India':city==='seattle'?'Seattle, Washington':'Location being planned')}}
function galleryProject(record,index){const p=payload(record),status=statusInfo(record),place=projectLocation(record),gallery=cityImages[place.city]?.gallery||[],image=gallery.length?gallery[index%gallery.length]:null;return`<article class="gallery-card ${index===0?'gallery-featured':''}">${image?`<img src="${esc(image)}" alt="${esc(place.label)} city view" loading="lazy">`:''}<div class="gallery-shade"></div><button class="circle-action" data-project="${record.id}" aria-label="Open ${esc(projectTitle(record))}">→</button><div class="gallery-content"><div class="eyebrow">${esc(p.client_name||'Client')} · ${esc(formatDate(p.shoot_date))}</div><h2>${esc(projectTitle(record))}</h2><div class="gallery-meta"><span>▣ ${esc(formatDate(p.shoot_date))}</span><span>⌖ ${esc(place.label)}</span></div><span class="status ${status[1]}">${status[0]}</span>${index===0?`<button class="primary gallery-cta" data-project="${record.id}">Open project →</button>`:`<button class="link gallery-link" data-project="${record.id}">View project →</button>`}</div></article>`}
function bind(){document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>go(button.dataset.view));document.querySelectorAll('[data-project]').forEach(button=>button.onclick=()=>go('project',button.dataset.project));document.querySelectorAll('[data-brief]').forEach(button=>button.onclick=()=>showBrief(button.dataset.brief));document.querySelectorAll('[data-production]').forEach(button=>button.onclick=()=>showProduction(button.dataset.production));document.querySelectorAll('[data-schedule]').forEach(button=>button.onclick=()=>showSchedule(button.dataset.schedule));document.querySelectorAll('[data-plan-approve]').forEach(button=>button.onclick=()=>approveProduction(button.dataset.planApprove));document.querySelectorAll('[data-generate-plan]').forEach(button=>button.onclick=()=>generateProduction(button.dataset.generatePlan));document.querySelectorAll('[data-generate-moodboard]').forEach(button=>button.onclick=()=>generateMoodboard(button.dataset.generateMoodboard))}
function overview(){setNav('overview');const attention=inquiries.filter(item=>['READY_FOR_REVIEW','CLIENT_CONFIRMED','CLIENT_CHANGE_REQUESTED'].includes(item.status)||item.production_pack&&!item.production_approved),scheduled=inquiries.filter(item=>item.status==='SCHEDULED').sort((a,b)=>String(a.call_time||payload(a).shoot_date||'').localeCompare(String(b.call_time||payload(b).shoot_date||''))),priority=attention[0]||scheduled[0],active=inquiries.filter(item=>item.status!=='SCHEDULED').slice(0,2).concat(inquiries.filter(item=>item.status==='SCHEDULED').slice(0,2)).slice(0,2);let priorityCard='<section class="overview-priority card"><div><div class="eyebrow">Studio status</div><h2>Everything is up to date.</h2><p class="muted">New client activity and planning tasks will appear here.</p></div><button class="secondary" data-view="inquiries">Open inquiry inbox →</button></section>';if(priority){const p=payload(priority),needsAction=attention.includes(priority),place=projectLocation(priority);priorityCard=`<section class="overview-priority card"><div><div class="eyebrow">${needsAction?'Needs your attention':'Next scheduled shoot'}</div><h2>${esc(needsAction?projectTitle(priority):p.client_name||projectTitle(priority))}</h2><p>${esc(needsAction?statusInfo(priority)[0].toLowerCase():`${formatDate(priority.call_time||p.shoot_date)} · ${place.label}`)}</p></div><button class="primary" data-project="${priority.id}">${needsAction?'Continue planning':'Open call sheet'} →</button></section>`}app.innerHTML=`<div class="overview-shell"><header class="overview-head"><div><div class="eyebrow">Photographer workspace</div><h1>Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc((sessionUser.name||'there').split(' ')[0])}.</h1><p class="lede">${inquiries.length} active shoot${inquiries.length===1?'':'s'} · ${attention.length?`${attention.length} item${attention.length===1?'':'s'} need your attention`:'Everything is up to date'}</p></div><button class="secondary" data-view="inquiries">Open inquiry inbox →</button></header>${priorityCard}<div class="overview-metrics"><div><b>${inquiries.filter(x=>x.status==='READY_FOR_REVIEW').length}</b><span>New inquiries</span></div><div><b>${inquiries.filter(x=>x.status==='NEEDS_INFORMATION').length}</b><span>Awaiting client</span></div><div><b>${inquiries.filter(x=>x.status==='CLIENT_CONFIRMED').length}</b><span>Ready to schedule</span></div><div><b>${scheduled.length}</b><span>Upcoming shoots</span></div></div><section class="overview-section"><div class="section-head"><div><div class="eyebrow">Coming up</div><h2 class="section-title">Upcoming schedule</h2></div><button class="link" data-view="calendar">View calendar →</button></div><div class="overview-schedule">${scheduled.slice(0,2).map(record=>{const p=payload(record);return`<article class="card schedule-preview"><time>${esc(formatDate(record.call_time||p.shoot_date))}</time><div><h3>${esc(p.client_name||projectTitle(record))}</h3><p class="muted">${esc(record.meeting_location||'Meeting location pending')}</p></div><button class="link" data-project="${record.id}">Open project →</button></article>`}).join('')||'<div class="card muted">No scheduled shoots yet.</div>'}</div></section><section class="overview-section"><div class="section-head"><div><div class="eyebrow">Current work</div><h2 class="section-title">Active projects</h2></div><button class="link" data-view="projects">View all projects →</button></div><div class="overview-projects">${active.map((record,index)=>galleryProject(record,index+1)).join('')||'<div class="card muted">No active projects yet.</div>'}</div></section></div>`;bind()}
function listView(kind){setNav(kind);const title=kind==='inquiries'?'Inquiry inbox':'Active projects',copy=kind==='inquiries'?'Every client request and follow-up in one place.':'Move each shoot from creative direction to production and scheduling.';if(kind==='projects'){app.innerHTML=`<div class="head"><div><div class="eyebrow">Photographer workspace</div><h1>${title}</h1><p class="lede">${copy}</p></div></div><div class="gallery-shell"><div class="gallery-grid">${inquiries.map(galleryProject).join('')||'<div class="card muted">Nothing here yet.</div>'}</div></div>`}else{app.innerHTML=`<div class="head"><div><div class="eyebrow">Photographer workspace</div><h1>${title}</h1><p class="lede">${copy}</p></div></div>${inquiries.map(recordCard).join('')||'<div class="card muted">Nothing here yet.</div>'}`}bind()}
function calendar(){setNav('calendar');const scheduled=inquiries.filter(x=>x.status==='SCHEDULED').sort((a,b)=>String(a.call_time).localeCompare(String(b.call_time)));app.innerHTML=`<div class="head"><div><div class="eyebrow">Shoot calendar</div><h1>Upcoming sessions</h1><p class="lede">Confirmed call times and meeting locations from your active projects.</p></div></div><div class="calendar">${scheduled.map(record=>{const p=payload(record);return`<article class="card"><div class="calendar-date">${esc(formatDate(record.call_time))}</div><h3>${esc(p.client_name)}</h3><p class="muted">${esc(record.meeting_location||'Meeting location pending')}</p><button class="link" data-project="${record.id}">Open project →</button></article>`}).join('')||'<div class="card muted">No shoots have been scheduled yet.</div>'}</div>`;bind()}
function progress(record){const hasMood=!!record.moodboard,hasPack=!!record.production_pack;return`<div class="progress"><div class="done"><b>01 · Inquiry</b>Details captured</div><div class="${hasMood?'done':''}"><b>02 · Creative direction</b>${hasMood?'Moodboard ready':'Brief review'}</div><div class="${hasPack?'done':''}"><b>03 · Production</b>${hasPack?'Plan created':'Shoot planning'}</div><div class="${record.status==='SCHEDULED'?'done':''}"><b>04 · Schedule</b>${record.status==='SCHEDULED'?'Shoot booked':'Client confirmation'}</div></div>`}
async function project(id){setNav('project');const record=await getRecord(id),p=payload(record),analysis=parse(record.analysis)||{},mood=parse(record.moodboard),status=statusInfo(record);let next='Waiting for the client to provide the remaining details.',button='';if(record.status==='SCHEDULED')next=`Shoot scheduled for ${formatDate(record.call_time)} at ${record.meeting_location}.`;else if(record.status==='CLIENT_CONFIRMED'){next='The client confirmed the plan. Set the final call time and meeting location.';button=`<button class="primary" data-schedule="${id}">Set shoot schedule →</button>`}else if(record.status==='CLIENT_CHANGE_REQUESTED'){next='The client requested a change. Review the inquiry and update the direction.';button=`<button class="primary" data-brief="${id}">Review creative brief →</button>`}else if(record.production_pack){next=record.production_approved?'The production plan is with the client for confirmation.':'Review and approve the production plan.';button=`<button class="primary" data-production="${id}">Review production pack →</button>`}else if(mood){next='The moodboard plan is drafted. Render image references when you are ready.';button=`<button class="primary" data-generate-plan="${id}">Generate production pack →</button>`}else if(record.status==='READY_FOR_REVIEW'){next='The inquiry is complete. Review the creative brief before generating references.';button=`<button class="primary" data-brief="${id}">Review creative brief →</button>`}app.innerHTML=`<button class="link" data-view="projects">← Back to Active projects</button><div class="detail-head"><div class="eyebrow">Active project · Inquiry #${record.id}</div><div class="row"><h1>${esc(p.client_name)}</h1><span class="status ${status[1]}">${status[0]}</span></div></div>${progress(record)}<div class="detail-grid"><section class="card"><div class="eyebrow">Client inquiry</div><p>${esc((p.message||'').split('\n\nClient follow-up answers:')[0])}</p><div class="followup"><div class="eyebrow">Client follow-up answers</div><p>${esc((p.message||'').includes('Client follow-up answers:')?p.message.split('Client follow-up answers:').slice(1).join(' '):'No follow-up answers recorded.')}</p></div><p class="quote">${esc(analysis.summary||'Agent summary is being prepared.')}</p><div class="meta"><div>Budget<b>${p.budget?'$'+esc(p.budget):'—'}</b></div><div>Date<b>${esc(formatDate(p.shoot_date))}</b></div><div>Contact<b>${esc(p.contact_email||p.client_email)}</b></div></div></section><aside class="card next"><div class="eyebrow">Your next move</div><h2>${esc(next)}</h2><div class="actions">${button}</div></aside></div>${mood?moodboardMarkup(mood,id):''}`;bind()}
function moodboardMarkup(mood,id){const tiles=mood.generated?.tiles||[],planTiles=mood.moodboard?.tiles||mood.tiles||[];const rendered=tiles.length>0;return`<section class="card moodboard"><div class="eyebrow">${rendered?'Rendered moodboard':'Moodboard plan draft'}</div><h2 class="section-title">${esc(mood.moodboard?.title||mood.generated?.title||mood.title||'Creative direction')}</h2>${rendered?`<div class="tiles">${tiles.map(tile=>`<figure><img src="${esc(tile.image_url)}" alt="${esc(tile.title)}"><figcaption>${esc(tile.title)}</figcaption></figure>`).join('')}</div>`:`<div class="moodboard-plan">${planTiles.map(tile=>`<article><b>${esc(tile.title)}</b><p>${esc(tile.caption||tile.styling_notes||'Visual reference to be rendered.')}</p></article>`).join('')}</div><div class="actions"><button class="primary" data-render-moodboard="${id}">Render moodboard images →</button><span class="muted">Uses your configured image-generation provider.</span></div>`}</section>`}
async function showBrief(id){current={view:'brief',id:Number(id)};setNav('brief');history.pushState(current,'',`/photographer?view=brief&id=${id}`);app.innerHTML='<div class="loading">Preparing the creative brief…</div>';try{const record=await getRecord(id),p=payload(record);let brief=briefCache.get(Number(id));if(!brief){const response=await fetch('/api/inquiries/brief',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({inquiry:p,client_answers:{},inquiry_id:Number(id)})});if(!response.ok)throw Error('Could not create the brief.');brief=await response.json();briefCache.set(Number(id),brief)}app.innerHTML=`<button class="link" data-project="${id}">← Back to project</button><div class="detail-head"><div class="eyebrow">Creative brief · ${esc(p.client_name)}</div><h1>${esc(brief.concept_name)}</h1><p class="lede">Review this direction before rendering the visual moodboard.</p></div><section class="card">${briefField('Creative summary',brief.creative_summary)}${briefField('Location',brief.location_direction)}${briefField('Lighting',brief.lighting_direction)}${briefField('Posing',brief.posing_direction)}${briefField('Wardrobe',brief.wardrobe_direction)}${briefField('Deliverables',(brief.deliverables||[]).join(', '))}${briefField('Budget notes',brief.budget_notes)}<div class="actions"><button class="primary" data-generate-moodboard="${id}">Approve brief and generate moodboard →</button></div><div id="operationStatus"></div></section>`;bind()}catch(error){showError(error.message)}}
const briefField=(title,value)=>`<div class="field-row"><b>${title}</b>${esc(value||'—')}</div>`;
async function generateMoodboard(id){const button=document.querySelector('[data-generate-moodboard]'),status=document.getElementById('operationStatus');button.disabled=true;button.textContent='Rendering moodboard…';status.innerHTML='<div class="notice">Generating four visual references. This can take a few minutes.</div>';try{const brief=briefCache.get(Number(id)),response=await fetch('/api/moodboards/create-and-generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({brief,inquiry_id:Number(id)})}),raw=await response.text();let data={};try{data=raw?JSON.parse(raw):{}}catch{data={detail:response.ok?'The server returned an unreadable response.':'Moodboard generation failed on the server.'}}if(!response.ok)throw Error(data.detail||data.error||'Moodboard generation failed.');await refresh();project(id)}catch(error){status.innerHTML=`<div class="error"><b>Moodboard was not generated.</b><br>${esc(error.message||'Please try again in a moment.')}</div>`;button.disabled=false;button.textContent='Try generating moodboard again →'}}
async function generateProduction(id){current={view:'production',id:Number(id)};history.pushState(current,'',`/photographer?view=production&id=${id}`);setNav('production');app.innerHTML='<div class="loading">Building the production pack…</div>';try{const record=await getRecord(id),p=payload(record);const response=await fetch(`/api/production-packs/create?inquiry_id=${id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({inquiry:p,client_answers:{},inquiry_id:Number(id)})});const data=await response.json();if(!response.ok)throw Error(data.detail||'Could not create the production pack.');await refresh();showProduction(id,false)}catch(error){showError(error.message)}}
async function showProduction(id,push=true){current={view:'production',id:Number(id)};if(push)history.pushState(current,'',`/photographer?view=production&id=${id}`);setNav('production');const record=await getRecord(id),pack=parse(record.production_pack);if(!pack){app.innerHTML=`<button class="link" data-project="${id}">← Back to project</button><div class="card"><h2>No production pack yet</h2><button class="primary" data-generate-plan="${id}">Generate production pack →</button></div>`;bind();return}app.innerHTML=`<button class="link" data-project="${id}">← Back to project</button><div class="detail-head"><div class="eyebrow">Production pack</div><h1>${esc(pack.title)}</h1><p class="lede">Review the shoot-day details before sharing the finalized plan with the client.</p></div><section class="card"><div class="eyebrow">Call sheet</div><div class="call-sheet">${Object.entries(pack.call_sheet||{}).map(([key,value])=>`<div><small>${esc(key)}</small><b>${esc(value)}</b></div>`).join('')}</div></section><div class="plan-grid">${planSection('Location plan',pack.location_plan)}${planSection('Shot list',pack.shot_list)}${planSection('Lighting plan',pack.lighting_plan)}${planSection('Wardrobe checklist',pack.wardrobe_checklist)}${planSection('Weather note',[pack.weather_note])}${planSection('Backup plan',[pack.backup_plan])}</div><section class="card"><div class="eyebrow">Photographer review</div>${record.production_approved?'<div class="notice"><b>Production pack approved</b><br>The client can now review and confirm this plan.</div>':`<p>This plan is ready to share with the client.</p><button class="primary" data-plan-approve="${id}">Approve production pack →</button>`}</section>`;bind()}
const planSection=(title,values)=>`<section class="card"><div class="eyebrow">${title}</div><ul>${(values||[]).map(value=>`<li>${esc(value)}</li>`).join('')}</ul></section>`;
async function approveProduction(id){const response=await fetch(`/api/inquiries/${id}/production/approve`,{method:'POST'});const data=await response.json();if(!response.ok||data.error){showError(data.detail||data.error||'Could not approve the production pack.');return}await refresh();showProduction(id,false)}
async function showSchedule(id){current={view:'schedule',id:Number(id)};history.pushState(current,'',`/photographer?view=schedule&id=${id}`);setNav('schedule');const record=await getRecord(id);app.innerHTML=`<button class="link" data-project="${id}">← Back to project</button><div class="detail-head"><div class="eyebrow">Final scheduling</div><h1>Set the shoot details.</h1><p class="lede">The client confirmed the plan. Choose the final call time and meeting point.</p></div><form class="card schedule-form" id="scheduleForm"><div class="field"><label for="callTime">Call time</label><input id="callTime" type="datetime-local" value="${esc(record.call_time||'')}" required></div><div class="field"><label for="meetingLocation">Meeting location</label><input id="meetingLocation" value="${esc(record.meeting_location||'')}" placeholder="e.g. Pike Place Market, main entrance" required></div><button class="primary" id="scheduleButton">Confirm schedule →</button><span id="scheduleStatus" class="muted"></span></form>`;bind();document.getElementById('scheduleForm').onsubmit=event=>saveSchedule(event,id)}
async function saveSchedule(event,id){event.preventDefault();const button=document.getElementById('scheduleButton'),status=document.getElementById('scheduleStatus');button.disabled=true;status.textContent='Saving schedule…';try{const response=await fetch(`/api/inquiries/${id}/schedule`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({call_time:document.getElementById('callTime').value,meeting_location:document.getElementById('meetingLocation').value})});const data=await response.json();if(!response.ok)throw Error(data.detail||'Could not save the schedule.');await refresh();project(id)}catch(error){status.textContent=error.message;button.disabled=false}}
function showError(message){app.innerHTML=`<div class="error"><b>Something went wrong</b><br>${esc(message)}</div><div class="actions"><button class="secondary" data-view="projects">Return to projects</button></div>`;bind()}
async function getRecord(id){const cached=inquiries.find(item=>item.id==id);if(cached)return cached;return fetch('/api/inquiries/'+id).then(response=>response.json())}
async function refresh(){const response=await fetch('/api/inquiries?photographer_email='+encodeURIComponent(sessionUser.email||''));inquiries=await response.json();const inboxCount=document.getElementById('inboxCount');if(inboxCount)inboxCount.textContent=inquiries.filter(x=>['READY_FOR_REVIEW','CLIENT_CONFIRMED','CLIENT_CHANGE_REQUESTED'].includes(x.status)).length||''}
function renderCurrent(){if(current.view==='overview')overview();else if(current.view==='inquiries'||current.view==='projects')listView(current.view);else if(current.view==='calendar')calendar();else if(current.view==='project')project(current.id);else if(current.view==='brief')showBrief(current.id);else if(current.view==='production')showProduction(current.id);else if(current.view==='schedule')showSchedule(current.id)}
async function editProduction(id){const record=await getRecord(id),pack=parse(record.production_pack);if(!pack)return;current={view:'production',id:Number(id)};app.innerHTML=`<button class="link" data-production="${id}">← Cancel editing</button><div class="detail-head"><div class="eyebrow">Production pack draft</div><h1>Edit the shoot plan</h1><p class="lede">Save a draft as often as needed. Sharing is a separate action.</p></div><form class="card" id="productionEditForm"><div class="field"><label>Plan title</label><input name="title" value="${esc(pack.title||'')}" required></div>${['location_plan','shot_list','lighting_plan','wardrobe_checklist'].map(key=>`<div class="field"><label>${esc(key.replaceAll('_',' '))}</label><textarea name="${key}" required>${esc((pack[key]||[]).join('\n'))}</textarea><small class="muted">One item per line</small></div>`).join('')}<div class="field"><label>Weather note</label><textarea name="weather_note" required>${esc(pack.weather_note||'')}</textarea></div><div class="field"><label>Backup plan</label><textarea name="backup_plan" required>${esc(pack.backup_plan||'')}</textarea></div>${Object.entries(pack.call_sheet||{}).map(([key,value])=>`<div class="field"><label>${esc(key.replaceAll('_',' '))}</label><input name="call_${esc(key)}" value="${esc(value)}"></div>`).join('')}<div class="actions"><button class="primary" type="submit">Save draft →</button><span id="draftStatus" class="muted"></span></div></form>`;bind();document.getElementById('productionEditForm').onsubmit=event=>saveProductionDraft(event,id,pack)}
async function saveProductionDraft(event,id,existing){event.preventDefault();const form=event.currentTarget,status=document.getElementById('draftStatus'),button=form.querySelector('button[type="submit"]'),value=name=>form.elements[name]?.value||'';button.disabled=true;status.textContent='Saving draft…';const lines=name=>value(name).split('\n').map(item=>item.trim()).filter(Boolean);const call_sheet=Object.fromEntries(Object.keys(existing.call_sheet||{}).map(key=>[key,value(`call_${key}`)]));const pack={title:value('title'),location_plan:lines('location_plan'),shot_list:lines('shot_list'),lighting_plan:lines('lighting_plan'),wardrobe_checklist:lines('wardrobe_checklist'),weather_note:value('weather_note'),backup_plan:value('backup_plan'),call_sheet};try{const response=await fetch(`/api/inquiries/${id}/production-pack`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(pack)}),data=await response.json();if(!response.ok)throw Error(data.detail||'Could not save the draft.');await refresh();status.textContent='Draft saved. Share it when ready.';setTimeout(()=>showProduction(id,false),500)}catch(error){status.textContent=error.message;button.disabled=false}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-edit-production]');if(button){event.preventDefault();editProduction(button.dataset.editProduction)}});
window.onpopstate=event=>{current=event.state||{view:'overview',id:null};renderCurrent()};
const renderProjectWithTimeline=project;project=async id=>{app.dataset.timelineId=id;await renderProjectWithTimeline(id);await refreshTimeline()};
const renderProductionWithEditing=showProduction;showProduction=async(id,push=true)=>{await renderProductionWithEditing(id,push);const record=await getRecord(id);if(!record.production_pack)return;const review=[...app.querySelectorAll('.card')].at(-1);if(review&&!review.querySelector('[data-edit-production]'))review.insertAdjacentHTML('beforeend',`<div class="actions"><button class="secondary" data-edit-production="${id}">Edit plan</button></div>`);const share=app.querySelector('[data-plan-approve]');if(share)share.textContent='Share plan with client →'};
async function init(){try{cityImages=await fetch('/static/city-images.json?v=2',{cache:'no-store'}).then(response=>response.json())}catch{cityImages={}}await refresh();const params=new URLSearchParams(location.search),view=params.get('view')||'overview',id=params.get('id');current={view,id:id?Number(id):null};renderCurrent()}
init();
setInterval(async()=>{
  if(['brief','production','schedule','messages','client-update','change-review','profile'].includes(current.view))return;
  await refresh();
  renderCurrent();
},10000);setInterval(()=>{const view=new URLSearchParams(location.search).get('view');if(['project','brief','production','schedule'].includes(view)){app.dataset.timelineId=new URLSearchParams(location.search).get('id')||'';refreshTimeline()}},2000);
async function showPhotographerMessages(id){const record=await getRecord(id),p=payload(record),response=await fetch(`/api/inquiries/${id}/messages`,{cache:'no-store'}),messages=response.ok?await response.json():[];setNav('project');app.innerHTML=`<button class="link" data-project="${id}">← Back to project</button><div class="detail-head"><div class="eyebrow">Client conversation</div><h1>${esc(p.client_name||'Client')}</h1><p class="lede">Messages for this inquiry stay with the production context.</p></div><section class="card conversation"><div class="conversation-list">${messages.map(message=>`<article class="message ${message.sender_role==='photographer'?'mine':''}"><small>${esc(message.sender_name)} · ${esc(formatDate(message.created_at))}</small><p>${esc(message.body)}</p></article>`).join('')||'<p class="muted">No messages yet. Start the conversation with the client.</p>'}</div><form id="photographerMessageForm" class="message-compose"><textarea id="messageBody" required maxlength="4000" placeholder="Write a message…"></textarea><div class="actions"><button class="primary">Send message →</button><span id="messageStatus" class="muted"></span></div></form></section>`;bind();document.getElementById('photographerMessageForm').onsubmit=event=>sendPhotographerMessage(event,id)}
async function sendPhotographerMessage(event,id){event.preventDefault();const button=event.currentTarget.querySelector('button'),status=document.getElementById('messageStatus'),body=document.getElementById('messageBody').value.trim();if(!body)return;button.disabled=true;status.textContent='Sending…';try{const response=await fetch(`/api/inquiries/${id}/messages`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({body,sender_role:'photographer',sender_name:sessionUser.name||'Photographer'})}),raw=await response.text();let data={};try{data=raw?JSON.parse(raw):{}}catch{data={detail:'The server could not send this message. Please try again.'}}if(!response.ok)throw Error(data.detail||'Could not send your message.');await showPhotographerMessages(id)}catch(error){status.textContent=error.message;button.disabled=false}}
const renderPhotographerProjectWithMessages=project;project=async id=>{await renderPhotographerProjectWithMessages(id);const actions=app.querySelector('.detail-grid .next .actions');if(actions&&!actions.querySelector('[data-message-client]'))actions.insertAdjacentHTML('beforeend',`<button class="secondary" data-message-client="${id}">Message client</button>`)};
const renderPhotographerWorkspace=renderCurrent;renderCurrent=()=>{if(current.view==='messages')return showPhotographerMessages(current.id);return renderPhotographerWorkspace()};
document.addEventListener('click',event=>{const button=event.target.closest('[data-message-client]');if(!button)return;event.preventDefault();go('messages',button.dataset.messageClient)});
const calendarNav=document.querySelector('.nav button[data-view="calendar"]');if(calendarNav)calendarNav.insertAdjacentHTML('beforebegin','<button data-view="messages"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M4 5h16v12H9l-5 3V5ZM8 10h8M8 14h5"/></svg></span><span>Messages</span></button>');document.querySelector('.nav button[data-view="messages"]')?.addEventListener('click',()=>go('messages'));
function photographerMessageInbox(){setNav('messages');app.innerHTML=`<div class="head"><div><div class="eyebrow">Client conversations</div><h1>Messages</h1><p class="lede">Keep every client conversation connected to its inquiry.</p></div></div><div class="conversation-inbox">${inquiries.map(record=>{const p=payload(record);return`<article class="card conversation-preview"><div><div class="eyebrow">Inquiry #${record.id}</div><h2>${esc(p.client_name||'Client')}</h2><p class="muted">${esc(projectTitle(record))}</p></div><button class="primary" data-message-client="${record.id}">Open conversation →</button></article>`}).join('')||'<div class="card muted">No client conversations yet.</div>'}</div>`;bind()}
const renderPhotographerMessageThread=showPhotographerMessages;showPhotographerMessages=async id=>{await renderPhotographerMessageThread(id);setNav('messages')};
function photographerProfile(){setNav('profile');app.innerHTML=`<div class="head"><div><div class="eyebrow">Studio profile</div><h1>Present your studio clearly.</h1><p class="lede">Clients see these details when choosing who to work with.</p></div></div><form class="card profile-form" id="photographerProfileForm"><div class="field"><label for="profileName">Name or studio name</label><input id="profileName" value="${esc(sessionUser.name||'')}" required maxlength="120"></div><div class="field"><label for="profileEmail">Email address</label><input id="profileEmail" value="${esc(sessionUser.email||'')}" disabled></div><div class="field"><label for="profileCity">City of work</label><input id="profileCity" value="${esc(sessionUser.city||'')}" placeholder="e.g. Seattle, WA" maxlength="120"></div><div class="field"><label for="profileSpecialties">Photography specialties</label><input id="profileSpecialties" value="${esc(sessionUser.specialties||'')}" placeholder="e.g. portraits, editorial, weddings" maxlength="300"></div><div class="field"><label for="profileBio">Studio bio <span>optional</span></label><textarea id="profileBio" maxlength="500" placeholder="Tell clients what you love to photograph.">${esc(sessionUser.bio||'')}</textarea></div><div class="actions"><button class="primary">Save profile →</button><span class="muted" id="profileStatus"></span></div></form>`;document.getElementById('photographerProfileForm').onsubmit=savePhotographerProfile}
async function savePhotographerProfile(event){event.preventDefault();const button=event.currentTarget.querySelector('button'),status=document.getElementById('profileStatus');button.disabled=true;status.textContent='Saving…';try{const response=await fetch('/api/auth/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:document.getElementById('profileName').value,city:document.getElementById('profileCity').value,bio:document.getElementById('profileBio').value,specialties:document.getElementById('profileSpecialties').value})}),data=await response.json();if(!response.ok)throw Error(data.detail||'Could not save your profile.');Object.assign(sessionUser,data);sessionStorage.setItem('shotcraftUser',JSON.stringify(sessionUser));document.getElementById('photographerName').textContent=sessionUser.name;status.textContent='Profile saved.'}catch(error){status.textContent=error.message}finally{button.disabled=false}}
document.addEventListener('click',event=>{const button=event.target.closest('.nav button');if(button&&button.textContent.trim()==='Profile'){event.preventDefault();go('profile')}});
const renderPhotographerWithProfile=renderCurrent;renderCurrent=()=>{if(current.view==='profile')return photographerProfile();return renderPhotographerWithProfile()};
const readProfileImage=file=>new Promise((resolve,reject)=>{if(!file)return resolve(null);if(!file.type.startsWith('image/'))return reject(Error('Choose an image file.'));if(file.size>2*1024*1024)return reject(Error('Profile pictures must be 2 MB or smaller.'));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read that image.'));reader.readAsDataURL(file)});
photographerProfile=()=>{setNav('profile');app.innerHTML=`<div class="head"><div><div class="eyebrow">Studio profile</div><h1>Present your studio clearly.</h1><p class="lede">Clients see these details when choosing who to work with.</p></div></div><form class="card profile-form" id="photographerProfileForm"><div class="profile-picture-field"><div class="profile-picture-preview">${sessionUser.profile_image?`<img src="${esc(sessionUser.profile_image)}" alt="Profile picture">`:'<span>◇</span>'}</div><div><label for="profileImage">Profile picture</label><input id="profileImage" type="file" accept="image/png,image/jpeg,image/webp"><small class="muted">PNG, JPEG, or WebP · 2 MB maximum</small></div></div><div class="field"><label for="profileName">Name or studio name</label><input id="profileName" value="${esc(sessionUser.name||'')}" readonly></div><div class="field"><label for="profileEmail">Email address</label><input id="profileEmail" value="${esc(sessionUser.email||'')}" disabled></div><div class="field"><label for="profileCity">City of work</label><input id="profileCity" value="${esc(sessionUser.city||'')}" placeholder="e.g. Seattle, WA" maxlength="120"></div><div class="field"><label for="profileSpecialties">Photography specialties</label><input id="profileSpecialties" value="${esc(sessionUser.specialties||'')}" placeholder="e.g. portraits, editorial, weddings" maxlength="300"></div><div class="field"><label for="profileBio">Studio bio <span>optional</span></label><textarea id="profileBio" maxlength="500" placeholder="Tell clients what you love to photograph.">${esc(sessionUser.bio||'')}</textarea></div><div class="actions"><button class="primary">Save profile →</button><span class="muted" id="profileStatus"></span></div></form>`;document.getElementById('photographerProfileForm').onsubmit=savePhotographerProfile};
savePhotographerProfile=async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button'),status=document.getElementById('profileStatus');button.disabled=true;status.textContent='Saving…';try{const image=await readProfileImage(document.getElementById('profileImage').files[0]);const response=await fetch('/api/auth/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({city:document.getElementById('profileCity').value,bio:document.getElementById('profileBio').value,specialties:document.getElementById('profileSpecialties').value,profile_image:image||sessionUser.profile_image||null})}),data=await response.json();if(!response.ok)throw Error(data.detail||'Could not save your profile.');Object.assign(sessionUser,data);sessionStorage.setItem('shotcraftUser',JSON.stringify(sessionUser));status.textContent='Profile saved.'}catch(error){status.textContent=error.message}finally{button.disabled=false}};
document.addEventListener('change',event=>{if(event.target?.id!=='profileImage')return;const file=event.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{const preview=document.querySelector('.profile-picture-preview');if(preview)preview.innerHTML=`<img src="${esc(reader.result)}" alt="Profile picture preview">`};reader.readAsDataURL(file)});
document.querySelector('.nav')?.insertAdjacentHTML('beforeend','<button data-view="profile"><span class="nav-icon">◯</span><span>Profile</span></button>');
const renderPhotographerMessagesWorkspace=renderCurrent;renderCurrent=()=>{if(current.view==='messages')return current.id?showPhotographerMessages(current.id):photographerMessageInbox();return renderPhotographerMessagesWorkspace()};
function updatePhotographerMessageNotices(){const total=inquiries.reduce((sum,record)=>sum+Number(record.unread_messages||0),0),messagesButton=document.querySelector('.nav button[data-view="messages"]');if(messagesButton){let badge=messagesButton.querySelector('.unread-message-badge');if(total){if(!badge){badge=document.createElement('span');badge.className='unread-message-badge';messagesButton.appendChild(badge)}badge.textContent=total>99?'99+':total;messagesButton.title=`${total} unread client message${total===1?'':'s'}`}else badge?.remove()}}
function decoratePhotographerUnread(){document.querySelectorAll('[data-project],[data-message-client]').forEach(button=>{const id=button.dataset.project||button.dataset.messageClient,record=inquiries.find(item=>item.id==id),count=Number(record?.unread_messages||0),card=button.closest('.card,.gallery-card');if(!count||!card||card.querySelector('.inquiry-unread'))return;card.insertAdjacentHTML('afterbegin',`<span class="inquiry-unread">${count} new message${count===1?'':'s'}</span>`)});updatePhotographerMessageNotices()}
const refreshPhotographerWithMessageNotices=refresh;refresh=async()=>{await refreshPhotographerWithMessageNotices();updatePhotographerMessageNotices()};
const openPhotographerMessageThread=showPhotographerMessages;showPhotographerMessages=async id=>{await fetch(`/api/inquiries/${id}/messages?reader_role=photographer`,{cache:'no-store'});await refresh();await openPhotographerMessageThread(id);updatePhotographerMessageNotices()};
const renderPhotographerInboxWithNotices=photographerMessageInbox;photographerMessageInbox=()=>{renderPhotographerInboxWithNotices();decoratePhotographerUnread()};
const renderPhotographerWorkspaceWithNotices=renderCurrent;renderCurrent=()=>{const output=renderPhotographerWorkspaceWithNotices();Promise.resolve(output).then(decoratePhotographerUnread);return output};
setTimeout(async()=>{await refresh();updatePhotographerMessageNotices();decoratePhotographerUnread()},0);
function photographerMessageInbox(){setNav('messages');const conversations=inquiries.filter(record=>Number(record.message_count||0)>0).sort((a,b)=>String(b.latest_message?.created_at||'').localeCompare(String(a.latest_message?.created_at||'')));app.innerHTML=`<div class="head"><div><div class="eyebrow">Client conversations</div><h1>Messages</h1><p class="lede">Only conversations that have been started, with each shoot’s essential context close at hand.</p></div></div><div class="conversation-inbox">${conversations.map(record=>{const p=payload(record),latest=record.latest_message||{},status=statusInfo(record),when=record.call_time?formatDate(record.call_time):p.shoot_date?`Preferred date · ${formatDate(p.shoot_date)}`:'Date to be confirmed',location=record.meeting_location||'Location being planned',unread=Number(record.unread_messages||0);return`<article class="card conversation-preview rich-conversation"><div class="conversation-main"><div class="conversation-heading"><div><div class="eyebrow">Inquiry #${record.id}</div><h2>${esc(p.client_name||'Client')}</h2></div><span class="status ${status[1]}">${status[0]}</span></div><p class="conversation-title">${esc(projectTitle(record))}</p><div class="conversation-context"><span>▣ ${esc(when)}</span><span>⌖ ${esc(location)}</span></div><div class="last-message"><b>${esc(latest.sender_name||'Client')}</b><span>${esc(latest.body||'')}</span><small>${esc(formatDate(latest.created_at))}</small></div></div><div class="conversation-action">${unread?`<span class="inquiry-unread inline-unread">${unread} new</span>`:''}<button class="primary" data-message-client="${record.id}">Open conversation →</button></div></article>`}).join('')||'<div class="card muted">No conversations have been started yet.</div>'}</div>`;bind();decoratePhotographerUnread()}
async function photographerCalendar(){setNav('calendar');const response=await fetch('/api/availability?photographer_email='+encodeURIComponent(sessionUser.email||'')+'&include_unavailable=true'),slots=response.ok?await response.json():[],requested=slots.filter(slot=>slot.status==='REQUESTED'),available=slots.filter(slot=>slot.status==='AVAILABLE'),booked=slots.filter(slot=>slot.status==='BOOKED');const clientName=id=>payload(inquiries.find(record=>record.id==id)||{}).client_name||'Client';app.innerHTML=`<div class="head"><div><div class="eyebrow">Shoot calendar</div><h1>Schedule & availability</h1><p class="lede">Offer times, review client requests, and confirm the final shoot schedule.</p></div></div><div class="availability-layout"><section class="card availability-create"><div class="eyebrow">Add availability</div><h2>Open a time for booking</h2><form id="availabilityForm"><div class="field"><label>Start</label><input name="starts_at" type="datetime-local" required></div><div class="field"><label>End</label><input name="ends_at" type="datetime-local" required></div><div class="field"><label>Meeting location</label><input name="location" placeholder="e.g. Pioneer Square, main entrance" required></div><div class="actions"><button class="primary">Add available time →</button><span id="availabilityStatus" class="muted"></span></div></form></section><section class="card availability-requests"><div class="eyebrow">Pending requests</div><h2>${requested.length} client request${requested.length===1?'':'s'}</h2>${requested.map(slot=>`<article class="availability-row"><div><b>${esc(clientName(slot.inquiry_id))}</b><span>${esc(formatDate(slot.starts_at))} – ${esc(new Date(slot.ends_at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}))}</span><small>${esc(slot.location)}</small></div><button class="primary" data-confirm-slot="${slot.id}">Confirm booking →</button></article>`).join('')||'<p class="muted">No pending time requests.</p>'}</section></div><section class="availability-section"><div class="section-head"><div><div class="eyebrow">Available times</div><h2 class="section-title">Ready for clients</h2></div></div><div class="availability-list">${available.map(slot=>`<article class="card availability-row"><div><b>${esc(formatDate(slot.starts_at))} – ${esc(new Date(slot.ends_at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}))}</b><span>${esc(slot.location)}</span></div><span class="status ready">AVAILABLE</span></article>`).join('')||'<p class="muted">No available times yet.</p>'}</div></section>${booked.length?`<section class="availability-section"><div class="eyebrow">Booked</div><div class="availability-list">${booked.map(slot=>`<article class="card availability-row"><div><b>${esc(formatDate(slot.starts_at))}</b><span>${esc(clientName(slot.inquiry_id))} · ${esc(slot.location)}</span></div><span class="status scheduled">BOOKED</span></article>`).join('')}</div></section>`:''}`;bind();document.getElementById('availabilityForm').onsubmit=saveAvailabilitySlot}
async function saveAvailabilitySlot(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),status=document.getElementById('availabilityStatus');button.disabled=true;status.textContent='Saving…';try{const response=await fetch('/api/availability?photographer_email='+encodeURIComponent(sessionUser.email||''),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))}),data=await response.json();if(!response.ok)throw Error(data.detail||'Could not add availability.');await photographerCalendar()}catch(error){status.textContent=error.message;button.disabled=false}}
async function confirmAvailabilitySlot(slotId){const response=await fetch(`/api/availability/${slotId}/confirm?photographer_email=${encodeURIComponent(sessionUser.email||'')}`,{method:'POST'}),data=await response.json();if(!response.ok){alert(data.detail||'Could not confirm this booking.');return}await refresh();photographerCalendar()}
document.addEventListener('click',event=>{const button=event.target.closest('[data-confirm-slot]');if(!button)return;event.preventDefault();confirmAvailabilitySlot(button.dataset.confirmSlot)});
calendar=photographerCalendar;
