/* AI Producer Queue — converts workflow state into concise human decisions. */
function producerQueueItems(){return inquiries.map(record=>{const p=payload(record),unread=Number(record.unread_messages||0),name=p.client_name||'Client',base={id:record.id,name,project:projectTitle(record)};if(unread)return{...base,tone:'message',eyebrow:'Client response',title:`${name} sent ${unread} new message${unread===1?'':'s'}`,summary:'The agent kept the conversation with this inquiry. Review the reply and decide the next step.',action:'Reply to client',view:'messages'};if(record.status==='CLIENT_CHANGE_REQUESTED')return{...base,tone:'change',eyebrow:'Plan feedback',title:`${name} requested a change`,summary:'The agent has kept the production context intact. Review the request before revising the plan.',action:'Review request',view:'project'};if(record.status==='CLIENT_CONFIRMED')return{...base,tone:'confirm',eyebrow:'Ready to book',title:`${name} approved the shoot plan`,summary:'Creative planning is complete. Confirm the final date, time, and location when ready.',action:'Open booking',view:'project'};if(record.status==='SCHEDULED'&&!record.client_update_sent)return{...base,tone:'update',eyebrow:'Client update',title:`${name}’s shoot is confirmed`,summary:'The agent can draft a concise confirmation with the final time and meeting point for you to review.',action:'Draft update',view:'client-update'};if(record.production_pack&&!record.production_approved)return{...base,tone:'share',eyebrow:'Plan ready',title:`${name}’s production pack is ready`,summary:'The agent compiled the shoot direction, logistics, and call sheet. Review it, then share it with the client.',action:'Review plan',view:'production'};if(record.moodboard&&!record.production_pack)return{...base,tone:'build',eyebrow:'Creative direction',title:`${name}’s moodboard is approved`,summary:'The visual direction is ready. Let the agent build the practical production pack next.',action:'Build production pack',view:'project'};if(record.status==='READY_FOR_REVIEW')return{...base,tone:'review',eyebrow:'New inquiry',title:`${name} is ready for creative review`,summary:'The agent captured the inquiry details. Review the brief and choose the creative direction.',action:'Review inquiry',view:'project'};return null}).filter(Boolean).slice(0,5)}
function producerQueueMarkup(){const items=producerQueueItems();return`<section class="producer-queue"><div class="producer-queue-head"><div><div class="eyebrow">AI producer queue</div><h2>Your next decision.</h2><p class="muted">The agent has completed the coordination work; this is the one action that benefits from your judgment.</p></div><span class="producer-count">${items.length} ${items.length===1?'decision':'decisions'}</span></div><div class="producer-queue-list">${items.map((item,index)=>`<article class="producer-item ${item.tone}"><span class="producer-index">0${index+1}</span><div class="producer-copy"><div class="eyebrow">${esc(item.eyebrow)} · Inquiry #${item.id}</div><h3>${esc(item.title)}</h3><p>${esc(item.summary)}</p></div><button class="primary" data-producer-action="${item.view}" data-producer-id="${item.id}">${esc(item.action)} →</button></article>`).join('')||'<article class="producer-empty"><span>✓</span><div><b>Your studio is clear.</b><p>The agent is monitoring active inquiries and will surface the next meaningful decision here.</p></div></article>'}</div></section>`}
const overviewWithProducerQueue=overview;overview=()=>{overviewWithProducerQueue();const metrics=app.querySelector('.overview-metrics');if(metrics)metrics.insertAdjacentHTML('afterend',producerQueueMarkup())};
async function showClientUpdateDraft(id){const record=await getRecord(id),p=payload(record);current={view:'client-update',id:Number(id)};history.pushState(current,'',`/photographer?view=client-update&id=${id}`);setNav('projects');app.innerHTML=`<button class="link" data-project="${id}">← Back to project</button><div class="detail-head"><div class="eyebrow">AI client update</div><h1>Review before you send.</h1><p class="lede">ShotCraft has drafted a concise confirmation using this shoot’s final details.</p></div><section class="card client-update-composer"><div class="update-context"><span>To</span><b>${esc(p.client_name||'Client')} · ${esc(p.client_email||'')}</b></div><div class="loading">Drafting a client update…</div></section>`;bind();try{const response=await fetch(`/api/inquiries/${id}/client-update-draft`,{method:'POST'}),raw=await response.text();let data={};try{data=raw?JSON.parse(raw):{}}catch{data={}}if(!response.ok)throw Error(data.detail||'Could not draft the update.');const composer=app.querySelector('.client-update-composer');composer.innerHTML=`<div class="update-context"><span>To</span><b>${esc(p.client_name||'Client')} · ${esc(p.client_email||'')}</b></div><form id="clientUpdateForm"><label for="clientUpdateBody">Message draft</label><textarea id="clientUpdateBody" required maxlength="1200">${esc(data.message)}</textarea><div class="actions"><button class="primary">Approve & send update →</button><button type="button" class="secondary" data-message-client="${id}">Open conversation</button><span class="muted" id="clientUpdateStatus"></span></div></form>`;document.getElementById('clientUpdateForm').onsubmit=event=>sendClientUpdate(event,id)}catch(error){app.querySelector('.client-update-composer').innerHTML=`<div class="error"><b>Could not draft the update.</b><br>${esc(error.message)}</div>`}}
async function sendClientUpdate(event,id){event.preventDefault();const form=event.currentTarget,button=form.querySelector('.primary'),status=document.getElementById('clientUpdateStatus'),body=document.getElementById('clientUpdateBody').value.trim();if(!body)return;button.disabled=true;status.textContent='Sending…';try{let response=await fetch(`/api/inquiries/${id}/messages`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({body,sender_role:'photographer',sender_name:sessionUser.name||'Photographer'})}),raw=await response.text(),data={};try{data=raw?JSON.parse(raw):{}}catch{}if(!response.ok)throw Error(data.detail||'Could not send the update.');response=await fetch(`/api/inquiries/${id}/client-update-sent`,{method:'POST'});if(!response.ok)throw Error('The update was sent, but the queue could not be refreshed.');await refresh();go('messages',id)}catch(error){status.textContent=error.message;button.disabled=false}}
