/* Structured scheduling: photographers propose concrete options; clients only
   select one of those persisted options. Chat is never the source of truth. */
async function showSchedule(id){
  current={view:'schedule',id:Number(id)};
  history.pushState(current,'',`/photographer?view=schedule&id=${id}`);
  setNav('schedule');
  const record=await getRecord(id),p=payload(record),duration=Number(p.duration_minutes||120),preferred=p.availability_windows||[];
  const preferredStart=String(preferred[0]||'').match(/^(\d{2}:\d{2})/)?String(preferred[0]).slice(0,5):'10:00';
  const base=new Date(`${p.shoot_date||new Date().toISOString().slice(0,10)}T${preferredStart}`);
  const local=value=>{const d=new Date(value);const offset=d.getTimezoneOffset();return new Date(d.getTime()-offset*60000).toISOString().slice(0,16)};
  const slot=(index)=>{const start=new Date(base);start.setDate(start.getDate()+index);const end=new Date(start.getTime()+duration*60000);return`<fieldset class="schedule-proposal"><legend>Option ${index+1}</legend><div class="form-grid"><div class="field"><label>Start</label><input name="start_${index}" type="datetime-local" value="${esc(local(start))}" required></div><div class="field"><label>End</label><input name="end_${index}" type="datetime-local" value="${esc(local(end))}" required></div></div></fieldset>`};
  app.innerHTML=`<button class="link" data-project="${id}">← Back to project</button><div class="detail-head"><div class="eyebrow">Propose shoot times</div><h1>Offer a few times that work.</h1><p class="lede">The client selects one exact option. It then returns here as a structured confirmation request.</p></div><section class="card schedule-client-context"><div class="eyebrow">Client preferences</div><div class="meta"><div>Requested duration<b>${esc(duration>=480?(duration===1440?'Up to 1 day':'Half day'):duration>=60?`${duration/60} hour${duration===60?'':'s'}`:`${duration} minutes`)}</b></div><div>Preferred date<b>${esc(formatDate(p.shoot_date))}</b></div></div>${preferred.length?`<div class="followup"><b>Availability shared by ${esc(p.client_name||'the client')}</b><ul>${preferred.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div>`:'<p class="muted">No availability windows were supplied. Propose options based on your availability.</p>'}</section><form class="card schedule-form" id="scheduleProposalForm">${slot(0)}${slot(1)}${slot(2)}<div class="field"><label>Meeting location</label><input id="proposalLocation" value="${esc(record.meeting_location||'')}" placeholder="e.g. Pike Place Market, main entrance" required></div><div class="actions"><button class="primary" id="proposalButton">Send time options to client →</button><span class="muted" id="proposalStatus"></span></div></form>`;
  bind();
  document.getElementById('scheduleProposalForm').onsubmit=event=>submitScheduleProposal(event,id);
}
async function submitScheduleProposal(event,id){
  event.preventDefault();
  const form=event.currentTarget,button=document.getElementById('proposalButton'),status=document.getElementById('proposalStatus'),location=document.getElementById('proposalLocation').value.trim();
  const suggestions=[0,1,2].map(index=>({starts_at:form.elements[`start_${index}`].value,ends_at:form.elements[`end_${index}`].value,location,rationale:'Proposed by your photographer.'}));
  button.disabled=true;status.textContent='Sending options to the client…';
  try{
    const response=await fetch(`/api/inquiries/${id}/schedule-proposals?photographer_email=${encodeURIComponent(sessionUser.email||'')}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({suggestions})}),data=await response.json();
    if(!response.ok)throw Error(data.detail||'Could not save these time options.');
    await refresh();
    go('project',id);
  }catch(error){status.textContent=error.message;button.disabled=false}
}

