const projectWithPreShootReadiness=project;project=async id=>{await projectWithPreShootReadiness(id);const record=await getRecord(id);if(record.status!=='SCHEDULED')return;const next=app.querySelector('.detail-grid .next');if(!next||next.querySelector('.pre-shoot-status'))return;const ready=record.pre_shoot_checkin?.status==='READY';next.insertAdjacentHTML('beforeend',`<div class="pre-shoot-status ${ready?'is-ready':''}"><div class="eyebrow">Pre-shoot check-in</div><b>${ready?'Client is ready for shoot day.':'Client has not completed their readiness check-in.'}</b><p>${ready?'ShotCraft recorded that they reviewed the essentials.':'The client can review the call sheet, wardrobe notes, and meeting location from their shoot plan.'}</p></div>`)};
/* Keep each project group in a predictable shoot-date order. */
function inboxDate(record){
  // Match the date shown on each inbox card. A final call time is only a
  // fallback when the client did not supply a preferred shoot date.
  const value=payload(record).shoot_date||record.call_time||record.updated_at;
  const timestamp=value?Date.parse(value):NaN;
  return Number.isFinite(timestamp)?timestamp:Number.MAX_SAFE_INTEGER;
}
/* A single Projects hub replaces the duplicate Inquiry inbox / Active projects
   navigation. Every workflow state stays available as a filter. */
document.querySelector('.nav button[data-view="inquiries"]')?.remove();
document.querySelector('.nav button[data-view="projects"] span:last-child').textContent='Projects';
function projectsHub(){
  setNav('projects');
  const needsAttention=inquiries.filter(record=>Number(record.unread_messages||0)>0||['READY_FOR_REVIEW','CLIENT_CHANGE_REQUESTED','CLIENT_CONFIRMED'].includes(record.status)),
    scheduled=inquiries.filter(record=>record.status==='SCHEDULED').sort((a,b)=>inboxDate(a)-inboxDate(b)),
    inProgress=inquiries.filter(record=>!needsAttention.includes(record)&&!scheduled.includes(record)).sort((a,b)=>inboxDate(a)-inboxDate(b)),
    sections=[
      ['Needs attention','Client messages, approvals, and shoot decisions that need your response.',needsAttention],
      ['In progress','Creative direction, moodboards, and production planning in motion.',inProgress],
      ['Scheduled','Confirmed sessions that are ready for shoot day.',scheduled],
    ];
  app.innerHTML=`<div class="head projects-head"><div><div class="eyebrow">Photographer workspace</div><h1>Projects</h1><p class="lede">A clear view of every shoot, organized by the next action.</p></div></div><div class="project-sections">${sections.map(([name,description,records])=>`<section class="project-section"><div class="section-head"><div><div class="eyebrow">${records.length} shoot${records.length===1?'':'s'}</div><h2 class="section-title">${name}</h2><p class="muted">${description}</p></div></div>${records.length?`<div class="gallery-grid project-section-grid">${records.map((record,index)=>galleryProject(record,index+1)).join('')}</div>`:'<div class="project-section-empty">Nothing in this section right now.</div>'}</section>`).join('')}</div>`;
  bind();
  decoratePhotographerUnread();
}
const renderPhotographerWithUnifiedProjects=renderCurrent;
