/* A month view keeps past shoot-day context visible and makes future months
   useful without turning the calendar into a narrow rolling window. */
const todayForCalendar=new Date();
let calendarMonthCursor=new Date(todayForCalendar.getFullYear(),todayForCalendar.getMonth(),1);
function calendarDayKey(day){return `${day.getFullYear()}-${String(day.getMonth()+1).padStart(2,'0')}-${String(day.getDate()).padStart(2,'0')}`}
function sameCalendarDay(left,right){return calendarDayKey(left)===calendarDayKey(right)}
async function photographerMonthlyCalendar(){
  setNav('calendar');
  const response=await fetch('/api/calendar?photographer_email='+encodeURIComponent(sessionUser.email||''),{cache:'no-store'}),data=response.ok?await response.json():{entries:[]},entries=data.entries||[],records=Object.fromEntries(inquiries.map(item=>[item.id,item]));
  const gridStart=new Date(calendarMonthCursor);gridStart.setDate(1-gridStart.getDay());
  const days=Array.from({length:42},(_,index)=>{const day=new Date(gridStart);day.setDate(gridStart.getDate()+index);return day});
  const inMonth=item=>{const date=new Date(item.starts_at);return !Number.isNaN(date.valueOf())&&date.getFullYear()===calendarMonthCursor.getFullYear()&&date.getMonth()===calendarMonthCursor.getMonth()};
  const monthEvents=entries.filter(inMonth),pending=entries.filter(item=>item.kind==='requested');
  app.innerHTML=`<div class="head"><div><div class="eyebrow">Shoot calendar</div><h1>Your studio, in rhythm.</h1><p class="lede">Review completed shoots, upcoming sessions, and client time preferences across any month.</p></div></div>${pending.length?`<section class="card scheduling-queue"><div><div class="eyebrow">Needs confirmation</div><h2>${pending.length} preferred time${pending.length===1?'':'s'} awaiting you</h2></div>${pending.map(item=>{const p=payload(records[item.inquiry_id]||{});return`<article><div><b>${esc(p.client_name||'Client')} · ${esc(photographerCalendarDate(item.starts_at))}</b><span>${esc(photographerCalendarTime(item.starts_at))} – ${esc(photographerCalendarTime(item.ends_at))} · ${esc(item.location||'Location to be confirmed')}</span></div><button class="primary" data-confirm-request="${item.inquiry_id}" data-time="${esc(item.starts_at)}" data-location="${esc(item.location||'Location to be confirmed')}">Review & confirm →</button></article>`}).join('')}</section>`:''}<section class="calendar-board calendar-month"><div class="calendar-board-head"><div class="calendar-month-nav"><button class="secondary calendar-month-button" data-calendar-month="-1" aria-label="Previous month">←</button><div><b>${esc(calendarMonthCursor.toLocaleDateString(undefined,{month:'long',year:'numeric'}))}</b><span>${monthEvents.filter(item=>item.kind==='scheduled').length} confirmed shoot${monthEvents.filter(item=>item.kind==='scheduled').length===1?'':'s'}</span></div><button class="secondary calendar-month-button" data-calendar-today>Today</button><button class="secondary calendar-month-button" data-calendar-month="1" aria-label="Next month">→</button></div></div><div class="calendar-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(day=>`<span>${day}</span>`).join('')}</div><div class="calendar-month-grid">${days.map(day=>{const key=calendarDayKey(day),events=entries.filter(item=>String(item.starts_at).slice(0,10)===key),outside=day.getMonth()!==calendarMonthCursor.getMonth();return`<article class="calendar-day ${events.length?'has-event':''} ${outside?'outside-month':''} ${sameCalendarDay(day,todayForCalendar)?'today':''}"><div><b>${day.getDate()}</b></div>${events.map(item=>{const p=payload(records[item.inquiry_id]||{});return`<button class="calendar-event ${item.kind}" data-project="${item.inquiry_id}">${esc(photographerCalendarTime(item.starts_at))}<span>${esc(p.client_name||'Client')} · ${esc(item.kind==='scheduled'?'Confirmed':'Requested')}</span></button>`}).join('')}</article>`}).join('')}</div></section>`;
  bind();
  document.querySelectorAll('[data-calendar-month]').forEach(button=>button.onclick=()=>{calendarMonthCursor.setMonth(calendarMonthCursor.getMonth()+Number(button.dataset.calendarMonth));photographerMonthlyCalendar()});
  document.querySelector('[data-calendar-today]')?.addEventListener('click',()=>{calendarMonthCursor=new Date(todayForCalendar.getFullYear(),todayForCalendar.getMonth(),1);photographerMonthlyCalendar()});
}
calendar=photographerMonthlyCalendar;
const monthlyCalendarStyles=document.createElement('style');
monthlyCalendarStyles.textContent='.calendar-month-nav{display:flex;align-items:center;gap:9px}.calendar-month-nav>div{display:grid;gap:2px;margin-right:4px}.calendar-month-nav b{font:inherit;font-weight:800}.calendar-month-nav span{color:#746f7a;font-size:12px}.calendar-month-button{min-width:36px;padding:7px 10px;font-size:12px}.calendar-weekdays,.calendar-month-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr))}.calendar-weekdays{border-bottom:1px solid #ded9e4;background:#faf8fd}.calendar-weekdays span{padding:10px 13px;color:#746f7a;font-size:11px;font-weight:800}.calendar-month-grid .calendar-day{min-height:126px}.calendar-month-grid .calendar-day:nth-child(7n){border-right:0}.calendar-day.outside-month{background:#fbfafc}.calendar-day.outside-month>div b{color:#aaa3af}.calendar-day.today>div b{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:#7057c7;color:#fff;font-size:15px}.calendar-month .calendar-event{margin-top:7px;padding:6px 7px;font-size:10px}@media(max-width:760px){.calendar-month-nav{flex-wrap:wrap}.calendar-weekdays span{padding:8px 5px;text-align:center}.calendar-month-grid{grid-template-columns:repeat(7,minmax(104px,1fr));overflow:auto}.calendar-month{overflow-x:auto}.calendar-month-grid .calendar-day{min-height:105px;padding:8px}}';
document.head.appendChild(monthlyCalendarStyles);

/* The generated production pack is a draft: the photographer owns every
   client-facing word before it is shared. */
const showProductionWithEditor=showProduction;showProduction=async(id,push=true)=>{await showProductionWithEditor(id,push);const record=await getRecord(id);if(record.production_approved||!record.production_pack)return;const review=app.querySelector('.plan-grid')?.nextElementSibling;if(review&&!review.querySelector('[data-edit-production]'))review.querySelector('.eyebrow')?.insertAdjacentHTML('afterend',`<div class="actions"><button class="secondary" data-edit-production="${id}">Edit draft details →</button></div>`)};
async function editProductionDraft(id){const record=await getRecord(id),pack=parse(record.production_pack);if(!pack)return;const lines=value=>(value||[]).join('\n');current={view:'production-edit',id:Number(id)};history.pushState(current,'',`/photographer?view=production-edit&id=${id}`);setNav('production');app.innerHTML=`<button class="link" data-production="${id}">← Back to production pack</button><div class="detail-head"><div class="eyebrow">Photographer edit</div><h1>Refine the client draft.</h1><p class="lede">Edit the creative direction and shoot-day details before sending this plan to the client.</p></div><form id="productionEditor" class="card"><div class="field"><label>Plan title</label><input name="title" value="${esc(pack.title)}" required></div><div class="field"><label>Location plan</label><textarea name="location_plan" required>${esc(lines(pack.location_plan))}</textarea></div><div class="field"><label>Shot list</label><textarea name="shot_list" required>${esc(lines(pack.shot_list))}</textarea></div><div class="field"><label>Lighting plan</label><textarea name="lighting_plan" required>${esc(lines(pack.lighting_plan))}</textarea></div><div class="field"><label>Wardrobe checklist</label><textarea name="wardrobe_checklist" required>${esc(lines(pack.wardrobe_checklist))}</textarea></div><div class="field"><label>Weather / contingency notes</label><textarea name="weather_note" required>${esc(pack.weather_note)}</textarea><textarea name="backup_plan" required>${esc(pack.backup_plan)}</textarea></div><div class="actions"><button class="primary">Save draft changes →</button><span class="muted" id="productionEditStatus"></span></div></form>`;bind();document.getElementById('productionEditor').onsubmit=event=>saveProductionDraft(event,id,pack)}
async function saveProductionDraft(event,id,pack){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),status=document.getElementById('productionEditStatus'),data=Object.fromEntries(new FormData(form)),list=name=>String(data[name]||'').split('\n').map(value=>value.trim()).filter(Boolean);button.disabled=true;status.textContent='Saving draft…';try{const response=await fetch(`/api/inquiries/${id}/production-pack`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({...pack,title:data.title,location_plan:list('location_plan'),shot_list:list('shot_list'),lighting_plan:list('lighting_plan'),wardrobe_checklist:list('wardrobe_checklist'),weather_note:data.weather_note,backup_plan:data.backup_plan})}),result=await response.json();if(!response.ok)throw Error(result.detail||'Could not save the draft.');await refresh();showProduction(id,false)}catch(error){status.textContent=error.message;button.disabled=false}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-edit-production]');if(!button)return;event.preventDefault();editProductionDraft(button.dataset.editProduction)});
const renderWithProductionEditor=renderCurrent;renderCurrent=()=>{if(current.view==='production-edit')return editProductionDraft(current.id);return renderWithProductionEditor()};

// Profile is a full workspace view too: rebind the persistent sidebar after it renders.
const renderPhotographerProfileWithNavigation=photographerProfile;
