/* Compact, photographer-authored scheduling options. */
showSchedule=async id=>{
  current={view:'schedule',id:Number(id)};
  history.pushState(current,'',`/photographer?view=schedule&id=${id}`);
  setNav('schedule');
  const record=await getRecord(id),p=payload(record),duration=Number(p.duration_minutes||120),preferred=String((p.availability_windows||[])[0]||'');
  const date=p.shoot_date||new Date().toISOString().slice(0,10),range=preferred.match(/(\d{2}:\d{2})\s*[–-]\s*(\d{2}:\d{2})/),start=`${date}T${range?.[1]||'10:00'}`;
  const addMinutes=(value,minutes)=>{const d=new Date(value);d.setMinutes(d.getMinutes()+minutes);return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`};
  const preferredEnd=range?`${date}T${range[2]}`:addMinutes(start,duration);
  const slotMarkup=(startsAt,endsAt,isPreferred=false)=>`<article class="schedule-option" data-slot><div class="schedule-option-head"><b>${isPreferred?'Client’s preferred time':'Time option'}</b><button type="button" class="link" data-remove-slot>Remove</button></div><div class="form-grid"><div class="field"><label>Start</label><input data-slot-start type="datetime-local" value="${esc(startsAt)}" required></div><div class="field"><label>End</label><input data-slot-end type="datetime-local" value="${esc(endsAt)}" required></div></div></article>`;
  app.innerHTML=`<button class="link" data-project="${id}">← Back to project</button><div class="detail-head"><div class="eyebrow">Propose shoot times</div><h1>Offer times that work.</h1><p class="lede">Start with the client’s preferred window, then add alternatives only if needed.</p></div><section class="card schedule-client-context"><div class="eyebrow">Client preference</div><div class="meta"><div>Requested duration<b>${esc(duration>=480?'Half day':duration>=60?`${duration/60} hour${duration===60?'':'s'}`:`${duration} minutes`)}</b></div><div>Preferred date<b>${esc(formatDate(p.shoot_date))}</b></div><div>Preferred time<b>${esc(preferred||'Not specified')}</b></div></div></section><form class="card schedule-form" id="scheduleProposalForm"><div id="scheduleOptions">${slotMarkup(start,preferredEnd,!!range)}</div><div class="actions"><button class="secondary" type="button" id="addScheduleSlot">Add another time</button><span class="muted">Up to five options.</span></div><div class="field"><label>Meeting location</label><input id="proposalLocation" value="${esc(record.meeting_location||p.location||'')}" placeholder="e.g. Pike Place Market, main entrance" required></div><div class="actions"><button class="primary" id="proposalButton">Send time options to client →</button><span class="muted" id="proposalStatus"></span></div></form>`;
  bind();
  const options=document.getElementById('scheduleOptions'),add=document.getElementById('addScheduleSlot');
  const updateControls=()=>{const rows=options.querySelectorAll('[data-slot]');add.disabled=rows.length>=5;rows.forEach(row=>{row.querySelector('[data-remove-slot]').hidden=rows.length===1})};
  add.onclick=()=>{const rows=options.querySelectorAll('[data-slot]'),last=rows[rows.length-1],lastEnd=last.querySelector('[data-slot-end]').value||preferredEnd;options.insertAdjacentHTML('beforeend',slotMarkup(lastEnd,addMinutes(lastEnd,duration)));updateControls()};
  options.onclick=event=>{const remove=event.target.closest('[data-remove-slot]');if(!remove)return;remove.closest('[data-slot]').remove();updateControls()};
  updateControls();
  document.getElementById('scheduleProposalForm').onsubmit=event=>submitScheduleProposal(event,id);
};
submitScheduleProposal=async(event,id)=>{
  event.preventDefault();
  const form=event.currentTarget,button=document.getElementById('proposalButton'),status=document.getElementById('proposalStatus'),location=document.getElementById('proposalLocation').value.trim();
  const suggestions=[...form.querySelectorAll('[data-slot]')].map(row=>({starts_at:row.querySelector('[data-slot-start]').value,ends_at:row.querySelector('[data-slot-end]').value,location,rationale:'Proposed by your photographer.'}));
  if(!suggestions.length){status.textContent='Add at least one time option.';return}
  button.disabled=true;status.textContent='Sending options to the client…';
  try{const response=await fetch(`/api/inquiries/${id}/schedule-proposals?photographer_email=${encodeURIComponent(sessionUser.email||'')}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({suggestions})}),data=await response.json();if(!response.ok)throw Error(data.detail||'Could not save these time options.');await refresh();go('project',id)}catch(error){status.textContent=error.message;button.disabled=false}
};

// Scheduling now sends the client confirmation automatically, so a completed
// shoot is not an additional producer decision.
producerQueueItems=()=>inquiries.map(record=>{
  const p=payload(record),unread=Number(record.unread_messages||0),change=record.change_request,name=p.client_name||'Client',base={id:record.id,name,project:projectTitle(record)};
  if(change?.status==='PENDING')return{...base,tone:'change',eyebrow:'Plan change detected',title:`${name} requested a plan change`,summary:change.assessment?.request_summary||'Review the requested update before changing the plan.',action:'Review proposed update',view:'change-review'};
  if(unread)return{...base,tone:'message',eyebrow:'Client response',title:`${name} sent ${unread} new message${unread===1?'':'s'}`,summary:'Review the reply and decide the next step.',action:'Reply to client',view:'messages'};
  if(record.status==='CLIENT_CONFIRMED')return{...base,tone:'confirm',eyebrow:'Ready to book',title:`${name} approved the shoot plan`,summary:'Creative planning is complete. Offer final time options for the client to choose from.',action:'Open booking',view:'project'};
  if(record.production_pack&&!record.production_approved)return{...base,tone:'share',eyebrow:'Plan ready',title:`${name}’s production pack is ready`,summary:'Review the direction, logistics, and call sheet, then share it with the client.',action:'Review plan',view:'production'};
  if(record.status==='READY_FOR_REVIEW')return{...base,tone:'review',eyebrow:'New inquiry',title:`${name} is ready for creative review`,summary:'Review the complete draft plan before sharing it with the client.',action:'Review inquiry',view:'project'};
  return null;
}).filter(Boolean).slice(0,5);

/* Share the production plan and photographer-authored booking options together. */
const showProductionWithTimeOptions=showProduction;
showProduction=async(id,push=true)=>{
  await showProductionWithTimeOptions(id,push);
  const record=await getRecord(id),review=app.querySelector('[data-plan-approve]')?.closest('section');
  if(!review||record.production_approved)return;
  const inquiry=payload(record),duration=Number(inquiry.duration_minutes||120),date=inquiry.shoot_date||new Date().toISOString().slice(0,10),range=String((inquiry.availability_windows||[])[0]||'').match(/(\d{2}:\d{2})\s*[–-]\s*(\d{2}:\d{2})/),start=`${date}T${range?.[1]||'10:00'}`;
  const plus=(value,minutes)=>{const d=new Date(value);d.setMinutes(d.getMinutes()+minutes);return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`};
  const slot=(from,to,index)=>`<article class="schedule-option" data-share-slot><div class="schedule-option-head"><b>${index===0?'Suggested time':'Alternative time'}</b><button class="link" type="button" data-remove-share-slot>Remove</button></div><div class="form-grid"><div class="field"><label>Start</label><input type="datetime-local" data-share-start value="${esc(from)}" required></div><div class="field"><label>End</label><input type="datetime-local" data-share-end value="${esc(to)}" required></div></div></article>`;
  review.innerHTML=`<div class="eyebrow">Send to client</div><h2>Share the plan and proposed time.</h2><p>Choose a time that works, add alternatives if useful, then send one complete plan for the client to approve.</p><form id="sharePlanForm"><div id="sharePlanSlots">${slot(start,range?`${date}T${range[2]}`:plus(start,duration),0)}</div><div class="actions"><button type="button" class="secondary" id="addShareSlot">Add another time</button><span class="muted">Up to three options.</span></div><div class="field"><label>Meeting location</label><input id="sharePlanLocation" value="${esc(record.meeting_location||inquiry.location||'')}" placeholder="e.g. Pike Place Market, main entrance" required></div><div class="actions"><button class="primary">Send plan & time options →</button><span class="muted" id="sharePlanStatus"></span></div></form>`;
  const slots=document.getElementById('sharePlanSlots'),add=document.getElementById('addShareSlot'),update=()=>{const rows=slots.querySelectorAll('[data-share-slot]');add.disabled=rows.length>=3;rows.forEach(row=>row.querySelector('[data-remove-share-slot]').hidden=rows.length===1)};
  add.onclick=()=>{const rows=slots.querySelectorAll('[data-share-slot]'),last=rows[rows.length-1],from=last.querySelector('[data-share-end]').value;slots.insertAdjacentHTML('beforeend',slot(from,plus(from,duration),rows.length));update()};
  slots.onclick=event=>{const remove=event.target.closest('[data-remove-share-slot]');if(remove){remove.closest('[data-share-slot]').remove();update()}};update();
  document.getElementById('sharePlanForm').onsubmit=event=>sharePlanWithTimes(event,id);
};
async function sharePlanWithTimes(event,id){event.preventDefault();const form=event.currentTarget,button=form.querySelector('.primary'),status=document.getElementById('sharePlanStatus'),location=document.getElementById('sharePlanLocation').value.trim(),suggestions=[...form.querySelectorAll('[data-share-slot]')].map(row=>({starts_at:row.querySelector('[data-share-start]').value,ends_at:row.querySelector('[data-share-end]').value,location,rationale:'Proposed by your photographer.'}));button.disabled=true;status.textContent='Sharing plan and time options…';try{let response=await fetch(`/api/inquiries/${id}/production/approve`,{method:'POST'}),data=await response.json();if(!response.ok||data.error)throw Error(data.detail||data.error||'Could not share the production plan.');response=await fetch(`/api/inquiries/${id}/schedule-proposals?photographer_email=${encodeURIComponent(sessionUser.email||'')}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({suggestions})});data=await response.json();if(!response.ok)throw Error(data.detail||'The plan was shared, but time options could not be sent.');await refresh();showProduction(id,false)}catch(error){status.textContent=error.message;button.disabled=false}}
